-- RRC014: coordinated MariaDB10.11 fresh strict session only; DATA proposal, not executed.
-- Adds58container entries; never updates/deletes/inserts a recipe or changes existing entry IDs.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE added_present INT DEFAULT 0;
 DECLARE locked_targets INT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF own_transaction THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF @@in_transaction<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 fresh transaction-free session required'; END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 strict SQL mode required'; END IF;
 IF @@SESSION.group_concat_max_len<1024 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 input-signature capacity insufficient'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN('tradeskill_recipe','tradeskill_recipe_entries','items','object') AND ENGINE='InnoDB')<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 InnoDB foundation mismatch'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe')<>16 OR (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe_entries')<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 target schema mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc014_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc014_old LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc014_added LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc014_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 CREATE TEMPORARY TABLE rrc014_stations(id INT PRIMARY KEY,zoneid INT,version INT,objectname VARCHAR(64),type INT,itemid INT) ENGINE=InnoDB;
 CREATE TEMPORARY TABLE rrc014_input_keys(recipe_id INT PRIMARY KEY,signature VARCHAR(512) NOT NULL) ENGINE=InnoDB;
 START TRANSACTION;
 SET own_transaction=TRUE;
 SELECT COUNT(*) INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*) INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*) INTO locked_targets FROM tradeskill_recipe r JOIN rrc014_recipes p ON p.id=r.id FOR UPDATE;
 IF locked_targets<>58 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 all58existing recipes required'; END IF;
 IF EXISTS(SELECT 1 FROM rrc014_recipes p LEFT JOIN tradeskill_recipe r ON r.id=p.id WHERE r.id IS NULL OR NOT(BINARY r.`content_flags` <=> BINARY p.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY p.`content_flags_disabled` AND r.`enabled` <=> p.`enabled` AND r.`id` <=> p.`id` AND r.`learned_by_item_id` <=> p.`learned_by_item_id` AND r.`max_expansion` <=> p.`max_expansion` AND r.`min_expansion` <=> p.`min_expansion` AND r.`must_learn` <=> p.`must_learn` AND BINARY r.`name` <=> BINARY p.`name` AND r.`nofail` <=> p.`nofail` AND BINARY r.`notes` <=> BINARY p.`notes` AND r.`quest` <=> p.`quest` AND r.`replace_container` <=> p.`replace_container` AND r.`skillneeded` <=> p.`skillneeded` AND r.`tradeskill` <=> p.`tradeskill` AND r.`trivial` <=> p.`trivial`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 recipe preimage drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc014_old p LEFT JOIN tradeskill_recipe_entries e ON (e.`componentcount` <=> p.`componentcount` AND e.`failcount` <=> p.`failcount` AND e.`id` <=> p.`id` AND e.`iscontainer` <=> p.`iscontainer` AND e.`item_id` <=> p.`item_id` AND e.`recipe_id` <=> p.`recipe_id` AND e.`salvagecount` <=> p.`salvagecount` AND e.`successcount` <=> p.`successcount`) WHERE e.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 oldentry preimage drift'; END IF;
 SELECT COUNT(*) INTO added_present FROM tradeskill_recipe_entries e JOIN rrc014_added a ON (e.`recipe_id` <=> a.`recipe_id` AND e.`item_id` <=> a.`item_id` AND e.`successcount` <=> a.`successcount` AND e.`failcount` <=> a.`failcount` AND e.`componentcount` <=> a.`componentcount` AND e.`salvagecount` <=> a.`salvagecount` AND e.`iscontainer` <=> a.`iscontainer`);
 IF added_present NOT IN(0,58) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 partial addition or multiplicity'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries e JOIN rrc014_recipes t ON t.id=e.recipe_id LEFT JOIN rrc014_old p ON (e.`componentcount` <=> p.`componentcount` AND e.`failcount` <=> p.`failcount` AND e.`id` <=> p.`id` AND e.`iscontainer` <=> p.`iscontainer` AND e.`item_id` <=> p.`item_id` AND e.`recipe_id` <=> p.`recipe_id` AND e.`salvagecount` <=> p.`salvagecount` AND e.`successcount` <=> p.`successcount`) LEFT JOIN rrc014_added a ON (e.`recipe_id` <=> a.`recipe_id` AND e.`item_id` <=> a.`item_id` AND e.`successcount` <=> a.`successcount` AND e.`failcount` <=> a.`failcount` AND e.`componentcount` <=> a.`componentcount` AND e.`salvagecount` <=> a.`salvagecount` AND e.`iscontainer` <=> a.`iscontainer`) WHERE p.id IS NULL AND a.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 foreign target entry or wrong new role'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe_entries e JOIN rrc014_recipes t ON t.id=e.recipe_id)<>465+added_present THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 target multiplicity mismatch'; END IF;
 IF added_present<>58 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 rollback requires exact whole added set'; END IF;
 DELETE e FROM tradeskill_recipe_entries e JOIN rrc014_added a ON (e.`recipe_id` <=> a.`recipe_id` AND e.`item_id` <=> a.`item_id` AND e.`successcount` <=> a.`successcount` AND e.`failcount` <=> a.`failcount` AND e.`componentcount` <=> a.`componentcount` AND e.`salvagecount` <=> a.`salvagecount` AND e.`iscontainer` <=> a.`iscontainer`);
 IF ROW_COUNT()<>58 OR (SELECT COUNT(*) FROM tradeskill_recipe)<>recipes_before OR (SELECT COUNT(*) FROM tradeskill_recipe_entries)<>entries_before-58 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 rollback delta mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc014_recipes p LEFT JOIN tradeskill_recipe r ON r.id=p.id WHERE r.id IS NULL OR NOT(BINARY r.`content_flags` <=> BINARY p.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY p.`content_flags_disabled` AND r.`enabled` <=> p.`enabled` AND r.`id` <=> p.`id` AND r.`learned_by_item_id` <=> p.`learned_by_item_id` AND r.`max_expansion` <=> p.`max_expansion` AND r.`min_expansion` <=> p.`min_expansion` AND r.`must_learn` <=> p.`must_learn` AND BINARY r.`name` <=> BINARY p.`name` AND r.`nofail` <=> p.`nofail` AND BINARY r.`notes` <=> BINARY p.`notes` AND r.`quest` <=> p.`quest` AND r.`replace_container` <=> p.`replace_container` AND r.`skillneeded` <=> p.`skillneeded` AND r.`tradeskill` <=> p.`tradeskill` AND r.`trivial` <=> p.`trivial`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 recipe preimage drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc014_old p LEFT JOIN tradeskill_recipe_entries e ON (e.`componentcount` <=> p.`componentcount` AND e.`failcount` <=> p.`failcount` AND e.`id` <=> p.`id` AND e.`iscontainer` <=> p.`iscontainer` AND e.`item_id` <=> p.`item_id` AND e.`recipe_id` <=> p.`recipe_id` AND e.`salvagecount` <=> p.`salvagecount` AND e.`successcount` <=> p.`successcount`) WHERE e.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 oldentry preimage drift'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe_entries e JOIN rrc014_recipes t ON t.id=e.recipe_id)<>465 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC014 restored target preimage count mismatch'; END IF;
 DROP TEMPORARY TABLE rrc014_recipes;
 DROP TEMPORARY TABLE rrc014_old;
 DROP TEMPORARY TABLE rrc014_added;
 DROP TEMPORARY TABLE rrc014_items;
 DROP TEMPORARY TABLE rrc014_stations;
 DROP TEMPORARY TABLE rrc014_input_keys;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC014',added_present,recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe),entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries),@@in_transaction;
END//
DELIMITER ;
